"""Run one fixed ownership/default qualification group, with no parallel Java work."""
import argparse
import importlib.util
import json
from pathlib import Path
import re
import subprocess
import sys

HERE = Path(__file__).resolve().parent
PHASE = HERE.parent
RETENTION = PHASE.parent / 'retention-followup'
DIRECT = PHASE.parent / 'direct-memo-followup'
PACKAGE = 'org/eclipse/rdf4j/sail/lmdb/evaluation/'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('stage', choices=('default', 'weak', 'always', 'fixed'))
    parser.add_argument('--runtime', type=Path, required=True)
    parser.add_argument('--attempt', required=True)
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if not args.slot_granted:
        raise ValueError('Exclusive Java slot required')
    spec = importlib.util.spec_from_file_location('historical_qualification', RETENTION / 'contracts/qualify_runtime.py')
    previous = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(previous)
    table = DIRECT / 'contracts/test-src' / (PACKAGE + 'NativeDirectValueMemoContractTest.java')
    integration = DIRECT / 'contracts/integration-src' / (PACKAGE + 'NativeDirectValueMemoIntegrationTest.java')
    retention = RETENTION / 'contracts/src' / (PACKAGE + 'NativeDirectValueMemoRetentionContractTest.java')
    if args.stage == 'default':
        selection = previous.FOCUSED + ',NativeDirectValueMemoContractTest,NativeDirectValueMemoIntegrationTest'
        enabled, policy, expected = 'false', 'strong', 138
        sources = [table, integration]
    elif args.stage == 'weak':
        methods = re.findall(r'\t@Test\n\tvoid (\w+)\(', table.read_text())
        if len(methods) != 20:
            raise ValueError('Historical table selection changed')
        methods.remove('strongOwnershipEndsWhenTheMemoCloses')
        selection = 'NativeDirectValueMemoContractTest#' + '+'.join(methods)
        selection += ',NativeDirectValueMemoIntegrationTest,NativeDirectValueMemoRetentionContractTest,' + previous.LIFETIME
        enabled, policy, expected = 'true', 'weak', 47
        sources = [table, integration, retention]
    else:
        selection = 'NativeDirectValueMemoIntegrationTest,NativeDirectValueMemoRetentionContractTest,' + previous.LIFETIME
        enabled, policy, expected = 'true', 'weak', 28
        sources = [integration, retention]
    command = [sys.executable, str(HERE / 'run_contracts.py'), args.attempt,
        '--classpath', str(args.runtime / 'classpath.txt'), '--overlay', str(args.runtime / 'classes')]
    for source in sources:
        command += ['--source', str(source)]
    command += ['--selection', selection, '--property', 'rdf4j.lmdb.nativeValueMemo.enabled=' + enabled,
                '--property', 'rdf4j.lmdb.nativeValueMemo.retention=' + policy]
    if args.stage != 'default':
        command += ['--property', 'rdf4j.lmdb.resultCoordinateTransport=off', '--property',
                    'rdf4j.lmdb.nativeValueMemo.admission=' + ('always' if args.stage in ('always', 'fixed') else 'initial')]
    command += ['--property', 'rdf4j.lmdb.nativeValueMemo.growth=' + ('fixed' if args.stage == 'fixed' else 'adaptive'), '--slot-granted']
    completed = subprocess.run(command, check=False)
    if completed.returncode:
        sys.exit(completed.returncode)
    receipt = json.loads((HERE / 'validation' / args.attempt / 'receipt.json').read_text())
    if not receipt['passed'] or receipt['results'] != dict(tests=expected, failures=0, errors=0, skipped=0):
        raise ValueError('Qualification count differs from the fixed group')
    print(json.dumps({'group': args.stage, 'passingTests': expected, 'attempt': args.attempt}))


if __name__ == '__main__':
    main()
